import { useEffect, useId, useRef, useState } from 'react';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import '@kerfjs/ui/layout.css';
import './item-dialog.css';

export type Item = { id: string; name: string; summary: string; owner: string; modified: string };
export function ItemDialog({ open, items, onClose, onChoose }: {
 open: boolean; items: Item[]; onClose: () => void; onChoose: (id: string) => void;
}) {
 const dialog = useRef<HTMLDialogElement>(null);
 const title = useId(), description = useId(), group = useId();
 const [selected, setSelected] = useState('');
 const item = items.find(item => item.id === selected) ?? items[0];
 useEffect(() => {
   const element = dialog.current;
   if (!element) return;
   if (open && !element.open) element.showModal();
   if (!open && element.open) element.close();
 }, [open]);
 return <dialog ref={dialog} className="kui-layout item-dialog" aria-labelledby={title} aria-describedby={description}
   onCancel={event => { event.preventDefault(); onClose(); }}>
   <DialogHeader><h2 id={title}>Choose a project</h2><p id={description}>Select a project to review its details, then open it.</p></DialogHeader>
   <div className="dialog-body">
     <fieldset className="item-master"><legend>Projects</legend>
       {items.length ? items.map(candidate => <label key={candidate.id}>
         <input type="radio" name={group} value={candidate.id} checked={item?.id === candidate.id} onChange={() => setSelected(candidate.id)} />
         {candidate.name}
       </label>) : <p>No projects available.</p>}
     </fieldset>
     <section className="item-detail" aria-label="Selected project">
       {item && <><h3>{item.name}</h3><p>{item.summary}</p><dl><dt>Owner</dt><dd>{item.owner}</dd><dt>Last modified</dt><dd>{item.modified}</dd></dl></>}
     </section>
   </div>
   <footer className="dialog-actions"><button type="button" onClick={onClose}>Cancel</button><button type="button" disabled={!item} onClick={() => item && onChoose(item.id)}>Open project</button></footer>
 </dialog>;
}

