.item-dialog { padding: 0; inline-size: min(52rem, calc(100vw - 2rem)); max-block-size: calc(100dvh - 2rem); overflow: hidden; }
.item-dialog[open] { display: flex; flex-direction: column; }
.item-dialog::backdrop { background: rgb(0 0 0 / .45); }
.dialog-body { display: grid; grid-template-columns: minmax(10rem, 1fr) minmax(0, 2fr); overflow: auto; min-block-size: 0; padding: var(--kui-space-4, 1rem); gap: var(--kui-space-4, 1rem); }
.item-master { margin: 0; padding: 0; border: 0; min-inline-size: 0; }
.item-master label { display: flex; align-items: center; min-height: 2.75rem; gap: var(--kui-space-2, .5rem); overflow-wrap: anywhere; }
.item-detail { min-inline-size: 0; overflow-wrap: anywhere; }
.item-detail dd { margin-inline-start: 0; }
.dialog-actions { display: flex; flex-wrap: wrap; justify-content: end; flex-shrink: 0; padding: var(--kui-space-4, 1rem); gap: var(--kui-space-2, .5rem); }
.item-dialog :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
@media (max-width: 36rem) { .dialog-body { grid-template-columns: minmax(0, 1fr); } }
